import { useState, useCallback, useEffect } from "react";
import { useRuntime } from "../RuntimeContext";
import { startBootstrapBroadcast, stopBootstrapBroadcast } from "../bootstrapBroadcast";
export function useRoom(peerId, initialRoomId) {
    const runtime = useRuntime();
    const [roomId, setRoomId] = useState(initialRoomId);
    const [inRoomState, setInRoomState] = useState(false);
    const runtimeWithCaps = runtime;
    const api = runtimeWithCaps?.capabilities?.get("peerBootstrap");
    useEffect(() => {
        if (!runtime)
            return;
        runtime.currentPeerId = peerId;
        runtime.inRoom = inRoomState;
    }, [runtime, peerId, inRoomState]);
    const join = useCallback(() => {
        if (!api?.joinRoom || !roomId.trim())
            return;
        if (!runtimeWithCaps?.bootstrapSignalingUrl) {
            startBootstrapBroadcast(runtimeWithCaps, roomId.trim(), peerId);
        }
        api.joinRoom(roomId.trim(), { id: peerId });
        setInRoomState(true);
    }, [api, runtimeWithCaps, roomId, peerId]);
    const joinInviteHost = useCallback(() => {
        if (!api?.joinRoom || !roomId.trim())
            return;
        api.joinRoom(roomId.trim(), { id: peerId }, { signalingMode: "invite" });
        setInRoomState(true);
    }, [api, roomId, peerId]);
    const leave = useCallback(() => {
        if (!api?.leaveRoom)
            return;
        if (!runtimeWithCaps?.bootstrapSignalingUrl && api.getSignalingMode?.() !== "invite") {
            stopBootstrapBroadcast();
        }
        runtimeWithCaps?.capabilities?.get("inviteLinks")?.clear?.();
        api.leaveRoom();
        setInRoomState(false);
    }, [api, runtimeWithCaps]);
    return {
        peerId,
        roomId,
        setRoomId,
        join,
        joinInviteHost,
        leave,
        inRoom: inRoomState,
        setInRoom: setInRoomState,
    };
}
