/**
 * Обмен SDP/ICE между вкладками через BroadcastChannel (без сигналинг-сервера).
 * Подписывается на bootstrap:* события runtime и пересылает их в канал комнаты;
 * принимает сообщения из канала и вызывает peerBootstrap.addRemoteOffer/Answer/Ice, connectToPeer.
 */
const CHANNEL_PREFIX = "grs-room-";
let channel = null;
let unsub = null;
function getPeerBootstrap(runtime) {
    return runtime.capabilities?.get("peerBootstrap");
}
/**
 * Запускает мост: подписка на bootstrap-события и отправка/приём через BroadcastChannel.
 * @param runtime — runtime с инициализированным peer-bootstrap
 * @param roomId — id комнаты (имя канала = grs-room-{roomId})
 * @param localPeerId — id текущего пира (чтобы не обрабатывать свои сообщения)
 */
export function startBootstrapBroadcast(runtime, roomId, localPeerId) {
    stopBootstrapBroadcast();
    const api = getPeerBootstrap(runtime);
    if (!api)
        return;
    const channelName = CHANNEL_PREFIX + roomId;
    channel = new BroadcastChannel(channelName);
    const handleMessage = (ev) => {
        const data = ev.data;
        if (!data || typeof data !== "object" || data.fromPeerId === localPeerId)
            return;
        const from = data.fromPeerId ?? data.peerId;
        if (!from)
            return;
        switch (data.type) {
            case "joined":
                api.connectToPeer?.(from);
                break;
            case "offer":
                if (data.sdp) {
                    api.addRemoteOffer?.(from, data.sdp).catch((err) => console.error("[bootstrap] addRemoteOffer failed", from, err));
                }
                break;
            case "answer":
                if (data.sdp) {
                    api.addRemoteAnswer?.(from, data.sdp).catch((err) => console.error("[bootstrap] addRemoteAnswer failed", from, err));
                }
                break;
            case "ice":
                if (data.candidate) {
                    api.addIceCandidate?.(from, data.candidate).catch((err) => console.error("[bootstrap] addIceCandidate failed", from, err));
                }
                break;
        }
    };
    channel.addEventListener("message", handleMessage);
    const offJoined = runtime.events.on("bootstrap:joined", (payload) => {
        if (payload?.peerId) {
            channel?.postMessage({ type: "joined", peerId: payload.peerId, fromPeerId: localPeerId });
        }
    });
    const offOffer = runtime.events.on("bootstrap:offer", (payload) => {
        channel?.postMessage({ type: "offer", peerId: payload.peerId, sdp: payload.sdp, fromPeerId: localPeerId });
    });
    const offAnswer = runtime.events.on("bootstrap:answer", (payload) => {
        channel?.postMessage({ type: "answer", peerId: payload.peerId, sdp: payload.sdp, fromPeerId: localPeerId });
    });
    const offIce = runtime.events.on("bootstrap:ice", (payload) => {
        channel?.postMessage({ type: "ice", peerId: payload.peerId, candidate: payload.candidate, fromPeerId: localPeerId });
    });
    unsub = () => {
        channel?.removeEventListener("message", handleMessage);
        channel?.close();
        channel = null;
        offJoined();
        offOffer();
        offAnswer();
        offIce();
        unsub = null;
    };
}
export function stopBootstrapBroadcast() {
    if (unsub) {
        unsub();
    }
}
