/**
 * Client-side runtime event logger. Subscribes to key GRS events for debugging.
 * Ref: task-logger.mdc. When core is built, prefer attachRuntimeLogger from @grstream/core.
 */
const LOG_PREFIX = "[GRS]";
const EVENTS = [
    "stream:created",
    "stream:processing",
    "stream:processed",
    "stream:error",
    "module:loading",
    "module:initialized",
    "module:error",
    "bootstrap:joined",
    "bootstrap:leave",
    "bootstrap:host-start",
    "bootstrap:offer-created",
    "bootstrap:offer-sent",
    "bootstrap:answer-received",
    "bootstrap:peer-connected",
    "bootstrap:peer-disconnected",
    "bootstrap:negotiation-error",
    "bootstrap:connection-failed",
    "invite:create",
    "invite:created",
    "invite:create-error",
    "room-ui/leave",
    "room-ui/create-invite",
];
export function attachRuntimeLogger(runtime) {
    const unsubs = EVENTS.map((event) => runtime.events.on(event, (payload) => {
        if (typeof console?.log === "function") {
            console.log(`${LOG_PREFIX} ${event}`, payload !== undefined ? payload : "");
        }
    }));
    return () => unsubs.forEach((off) => off());
}
