/**
 * Bridge: subscribes to invite:create, calls startBootstrapInviteHost + addLink, emits invite:created.
 * Keeps room-ui decoupled from bootstrap-invite (room-ui only emits events).
 * Ref: module-system.mdc, stream-graph.mdc (event-driven).
 */
import { useEffect } from "react";
import { useRuntime } from "./RuntimeContext";
import { startBootstrapInviteHost } from "@grstream/bootstrap-invite";
const INVITE_CREATE = "invite:create";
const INVITE_CREATED = "invite:created";
const INVITE_CREATE_ERROR = "invite:create-error";
export function InviteCreateBridge() {
    const runtime = useRuntime();
    useEffect(() => {
        if (!runtime?.capabilities)
            return;
        const off = runtime.events.on(INVITE_CREATE, async () => {
            try {
                const result = await startBootstrapInviteHost(runtime);
                const inviteLinks = runtime.capabilities?.get("inviteLinks");
                inviteLinks?.addLink?.({
                    inviteId: result.inviteId,
                    url: result.url,
                    token: result.token,
                });
                runtime.events.emit(INVITE_CREATED, result);
            }
            catch (e) {
                runtime.events.emit(INVITE_CREATE_ERROR, {
                    message: e instanceof Error ? e.message : "Create invite failed",
                });
            }
        });
        return off;
    }, [runtime]);
    return null;
}
