  --side-panel-width: 340px;
  --video-max-width: 1400px;

  --bg-main: #1a1a2e;
  --bg-panel: #16162a;
  --bg-elevated: #252540;

  --border-color: #444;
  --border-color-strong: #555;

  --breakpoint-side: 900px;
  --breakpoint-narrow: 600px;
}


/* ============================= */
/* Root Layout                   */
/* ============================= */

.mainPage--t4AxN {
  padding: var(--page-padding);
  min-height: 100vh;
  background: var(--bg-main);
  box-sizing: border-box;
}

.layoutRoot--a58Sy {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 0 8px;
  height: 100%;
  position: relative;
}


/* ============================= */
/* Top bar                       */
/* ============================= */

.topBar--olTF6 {
  display: flex;
  align-items: center;

  background: var(--bg-panel);

  border-radius: 12px;
  border: 1px solid var(--border-color);

  flex-shrink: 0;
}


/* ============================= */
/* Main content                  */
/* ============================= */

.mainArea--k4GiK {
  display: flex;
  gap: 8px;

  flex: 1 1 auto;

  min-height: 0;

  align-items: stretch;
}


