export function getRoomIdFromUrl() {
    if (typeof window === "undefined")
        return "";
    const params = new URLSearchParams(window.location.search);
    return params.get("room")?.trim() ?? "";
}
export function buildInviteLink(roomId) {
    const base = typeof window !== "undefined" ? window.location.origin + window.location.pathname : "";
    return `${base}?room=${encodeURIComponent(roomId)}`;
}
export function getInviteFromUrl() {
    if (typeof window === "undefined")
        return null;
    const params = new URLSearchParams(window.location.search);
    return params.get("invite")?.trim() ?? null;
}
export function getAnswerFromUrl() {
    if (typeof window === "undefined")
        return "";
    const params = new URLSearchParams(window.location.search);
    const raw = params.get("answer")?.trim() ?? "";
    return raw ? decodeURIComponent(raw) : "";
}
export function getAnswerLink(token) {
    if (typeof window === "undefined")
        return `?answer=${encodeURIComponent(token)}`;
    const base = window.location.origin + window.location.pathname;
    return `${base}?answer=${encodeURIComponent(token)}`;
}
